Config = {}
Config.KitItem = 'antilag_kit'
Config.InstallTime = 10000
Config.RemoveTime = 10000
Config.MechanicJobs = { mechanic=true, mechanic2=true }

Config.MinSpeedKmh = 5.0
Config.Range = 220.0

-- V4.4.2 sound source:
--   'synth'  = pops/bangs generated by the resource itself (html/index.html). Always works,
--              no GTA audio banks needed. Volume/muffling by distance. (default)
--   'native' = GTA soundsets below. Depends on game audio banks; can be silent on some setups.
Config.SoundMode = 'synth'
Config.SoundVolume = 0.9   -- 0.0 - 1.5
Config.SoundRange = 120.0  -- metres; beyond this nearby players hear nothing

-- Native GTA audio (only used when Config.SoundMode = 'native'). Optional `bank = '...'`
-- per sound is loaded with RequestScriptAudioBank first. These are emitted FROM the vehicle, so GTA handles 3D positioning.
Config.NativeSounds = {
    pop  = { name = 'BOOT_POP', set = 'DLC_VW_BODY_DISPOSAL_SOUNDS' },
    bang = { name = 'Explosion_01', set = 'FBI_HEIST_ELEVATOR_SHAFT_DEBRIS_SOUNDS' },
    mega = { name = 'Explosion_04', set = 'FBI_HEIST_ELEVATOR_SHAFT_DEBRIS_SOUNDS' },
    big  = { name = 'Explosion_04', set = 'FBI_HEIST_ELEVATOR_SHAFT_DEBRIS_SOUNDS' }
}

-- V4 uses driver input instead of addon-dependent RPM values.
Config.LimiterThrottle = 0.82
Config.LimiterHoldMs = 300
Config.LiftThrottleBefore = 0.55
Config.LiftThrottleAfter = 0.08
Config.LiftCooldownMs = 520

-- Burst patterns: { kind, gap after this shot in ms }. kind = 'pop' | 'bang' | 'mega' | 'big'.
-- Keep gaps >= 75ms so nearby players receive every shot (server rate gate is 70ms).
-- (The held-throttle 2-step is a continuous barrage, see Config.Intensity.)
Config.LiftSequence = {         -- lift off at speed
    { 'bang', 100 }, { 'pop', 90 }, { 'mega', 240 }, { 'big', 0 }
}

-- BIG bangs: a separate, much heavier explosion that lands after the crackle.
Config.BigBang = {
    CrackleFinale = true,    -- end every overrun crackle with a BIG bang
    FinaleDelayMs = 150,     -- pause after the last crackle before the BIG bang
    CrackleChance = 0.04,    -- chance any crackle shot is a BIG bang
    Shake = 0.025,           -- camera shake for players close by (0 = off, 0.1 = heavy)
    ShakeRange = 12.0,       -- metres
}
Config.HugeFlameScale = 3.0  -- flame size for BIG bangs

-- Gear change: pops -> bang -> BIG bang on every shift while driving.
Config.GearChange = {
    Enabled = true,
    Downshifts = false,      -- true = also fire on downshifts
    MinSpeedKmh = 10.0,
    CooldownMs = 700,        -- ignore shifts closer together than this
    Sequence = { { 'pop', 80 }, { 'pop', 85 }, { 'bang', 180 }, { 'big', 0 } },
}

Config.FlameScale = 1.55
Config.BigFlameScale = 2.15

---------------------------------------------------------------------
-- V4.4 POPS & BANGS (overrun crackle)
---------------------------------------------------------------------
-- A "pops & bangs" map: while coasting off-throttle the exhaust keeps crackling
-- with irregular pops and the occasional bang until you get back on it or slow down.
-- Can be switched on/off per vehicle from the /antilag menu.
Config.PopsBangs = {
    Enabled = true,          -- master switch for the whole feature
    DefaultOn = true,        -- state for newly fitted vehicles
    MinSpeedKmh = 25.0,      -- only crackle above this speed
    MaxThrottle = 0.08,      -- counts as "off throttle" at or below this
    StartDelayMs = 800,      -- wait after lift-off before the crackle starts (lets the lift burst + BIG bang play)
    MaxDurationMs = 4500,    -- stop crackling after this long on the overrun
    MinGapMs = 90,           -- shortest gap between pops (server rate gate is 70ms)
    MaxGapMs = 260,          -- longest gap between pops
    BangChance = 0.30,       -- chance any shot is a bang instead of a pop
    MegaChance = 0.15,       -- chance any shot is a mega bang
    FlameChance = 0.55,      -- chance a plain pop also spits a flame (bangs always flame)
}

---------------------------------------------------------------------
-- V4.4 FLAME COLOURS
---------------------------------------------------------------------
-- Who may change a fitted vehicle's settings from the panel:
--   'driver'   = whoever is in the driver seat of a fitted vehicle
--   'mechanic' = only mechanics (Config.MechanicJobs) in the driver seat
Config.SettingsPermission = 'driver'

-- Command that opens the 2-Step panel (driver seat of a fitted vehicle).
Config.MenuCommand = 'antilag'

-- Allow picking any colour with the colour picker, not just the presets.
Config.AllowCustomColour = true

-- Default colour for newly fitted vehicles (a preset key below).
Config.DefaultFlameColour = 'stock'

-- The tint is multiplied onto GTA's flame texture, so bright saturated colours read best.
-- rgb = nil means untouched stock GTA flame. 'rainbow' cycles through the spectrum shot by shot.
-- How coloured flames are drawn. GTA's normal backfire flame is orange and ignores tint, so
-- coloured flames use a different GTA FLAME effect that is tinted instead.
-- In a car, type /antilagfx to see every option below in your colour (or /antilagfx 3 for one),
-- then set Config.ColourFx to the number that looks best.
--   hideStock = true  -> only the coloured flame (no orange flame underneath)
--   rot = { pitch, roll, yaw } to aim the flame out of the back of the car
-- Got a custom recoloured flame particle (.ypt) streamed on your server? Add it here as
-- another entry with its asset and effect name.
Config.ColourFx = 1
Config.ColourFxOptions = {
    { label = 'Nitrous exhaust flame',       asset = 'veh_xs_vehicle_mods', name = 'veh_nitrous', scale = 1.2, looped = true, durationMs = 170, hideStock = true },
    { label = 'Nitrous + stock flame',       asset = 'veh_xs_vehicle_mods', name = 'veh_nitrous', scale = 1.0, looped = true, durationMs = 170, hideStock = false },
    { label = 'Jet afterburner flame',       asset = 'core', name = 'veh_exhaust_afterburner', scale = 1.2, looped = true, durationMs = 170, hideStock = true },
    { label = 'Fire jet (A)',                asset = 'core', name = 'ent_sht_flame', scale = 0.6, looped = true, durationMs = 170, rot = { 90.0, 0.0, 0.0 }, hideStock = true },
    { label = 'Fire jet (B)',                asset = 'core', name = 'ent_sht_flame', scale = 0.6, looped = true, durationMs = 170, rot = { -90.0, 0.0, 0.0 }, hideStock = true },
    { label = 'Wreck fire',                  asset = 'core', name = 'fire_wrecked_plane_cockpit', scale = 0.35, looped = true, durationMs = 200, hideStock = true },
    { label = 'Tinted backfire (one-shot)',  asset = 'core', name = 'veh_backfire', scale = 1.0, looped = false, hideStock = true },
    { label = 'Tinted backfire (looped)',    asset = 'core', name = 'veh_backfire', scale = 1.0, looped = true, durationMs = 140, hideStock = true },
}

-- Coloured light flash at the exhaust on every flame (also for stock, in orange).
