-- Intensity levels. While you hold the limiter the 2-step fires a continuous barrage
-- (like a real 2-step): one shot every gap ms (random between min and max), each shot
-- picked from mix by weight. flame multiplies the flame size, chance = chance each
-- shot actually fires (lower = more ragged), maxSpeed = 2-step speed window (km/h).
Config.Intensity = {
    soft = {
        label = 'Soft', flame = 0.80, chance = 0.80, maxSpeed = 8.0,
        gap = { 190, 270 },
        mix = { pop = 0.70, bang = 0.30 },
    },
    moderate = {
        label = 'Moderate', flame = 1.00, chance = 0.95, maxSpeed = 12.0,
        gap = { 130, 180 },
        mix = { pop = 0.45, bang = 0.47, mega = 0.08 },
    },
    max = {
        label = 'Maximum', flame = 1.25, chance = 1.0, maxSpeed = 16.0,
        gap = { 105, 150 },
        mix = { pop = 0.30, bang = 0.50, mega = 0.15, big = 0.05 },
    },
}

-- Launch control: hold the handbrake + throttle while stopped. RPM is held at the limiter
-- set in the panel and the 2-step fires at the launch intensity. Release the handbrake to go.
Config.LaunchControl = {
    HoldControl = 76,        -- 76 = handbrake (SPACE / RB)
    MinRpm = 0.45,           -- lowest limiter the panel allows (0.0 - 1.0 of redline)
    MaxRpm = 0.95,
    DefaultRpm = 0.70,
}

-- Popcorn mode: while on the limiter, a chance of a rapid-fire string of pops.
Config.Popcorn = {
    Chance = 0.35,
    CooldownMs = 2200,
    Shots = { 6, 10 },       -- min, max pops in a string
    GapMs = { 75, 110 },     -- min, max gap between them
}

-- Flame size slider range in the panel (multiplier on every flame).
Config.FlameSize = { Min = 0.5, Max = 2.0, Default = 1.0 }

-- Hotbar: three presets per vehicle. Press the key while driving to open it, then 1 / 2 / 3.
Config.Hotbar = {
    Enabled = true,
    Key = 'N',               -- default keybind (players can rebind in GTA settings > FiveM)
}

-- Test mode (Colors tab > TEST): the car is frozen, hold handbrake + throttle to rev and see
-- the unsaved flame, firing at the draft's intensity. Backspace ends it.
